void ADFTypes::AccomplishmentRule::read(IO::File& buffer) {
    AccomplishmentIdHash = buffer.read_pod<uint32>();
    OrbisIndex = buffer.read_pod<int32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        SteamId = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    ChallengeNameHash = buffer.read_pod<uint32>();
    SessionForwardedEvent = buffer.read_pod<uint32>();
    Operator = static_cast<ADFTypes::StatsOperator>(buffer.read_pod<uint32>());
    Threshold = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        UnlockedEvent = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    EvaluationStatHash = buffer.read_pod<uint32>();
    buffer.skip(4);
    StatNameIds.read(buffer);
}

