void ADFTypes::ItemLibraryPost::read(IO::File& buffer) {
    excel_alias = buffer.read_pod<uint32>();
    name_localization_id = buffer.read_pod<uint32>();
    icon_hash = buffer.read_pod<uint32>();
    img_hash = buffer.read_pod<uint32>();
    desc_localization_id = buffer.read_pod<uint32>();
    barter_value = buffer.read_pod<uint16>();
    item_type = buffer.read_pod<uint8>();
    item_sub_type = buffer.read_pod<uint8>();
    category = buffer.read_pod<uint32>();
    upgrade_slots = buffer.read_pod<uint8>();
    disposable_slots = buffer.read_pod<uint8>();
    nr_of_properties = buffer.read_pod<uint8>();
    max_stack = buffer.read_pod<uint8>();
    spawn_name = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        animation_modifier = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    pickup_name = buffer.read_pod<uint32>();
    for(int i = 0; i < 6; ++i) {
        item_property_value[i] = buffer.read_pod<uint16>();
    }
    for(int i = 0; i < 6; ++i) {
        item_properties[i] = buffer.read_pod<uint8>();
    }
    buffer.skip(2);
    for(int i = 0; i < 6; ++i) {
        item_property_hashes[i] = buffer.read_pod<uint32>();
    }
    equip_flags = buffer.read_pod<uint32>();
    health = buffer.read_pod<int16>();
    size = buffer.read_pod<uint8>();
    buffer.skip(9);
}

