void ADFTypes::CarCombatAttack::read(IO::File& buffer) {
    MoveStartTime = buffer.read_pod<float32>();
    ClaimStartTime = buffer.read_pod<float32>();
    ClaimSucceedTimeout = buffer.read_pod<float32>();
    Timeout = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        SourceAttackPosition = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        TargetAttackPosition = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    AttackType = buffer.read_pod<uint8>();
    Optional = buffer.read_pod<uint8>();
    buffer.skip(6);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        DebugName = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

