void ADFTypes::SpellPost::read(IO::File& buffer) {
    name_id = buffer.read_pod<uint32>();
    type_id = buffer.read_pod<uint32>();
    targeting_type = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        damage_act = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        hit_event = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    hit_pause = buffer.read_pod<uint32>();
    damage_upgrade_level_name = buffer.read_pod<uint32>();
    min_damage = buffer.read_pod<uint32>();
    max_damage = buffer.read_pod<uint32>();
    friendly_damage_multiplier = buffer.read_pod<float32>();
    buffer.skip(4);
    spell_effects.read(buffer);
}

