void ADFTypes::PhysicsVehicleAxleDesc::read(IO::File& buffer) {
    Length = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        Direction[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        Offset[i] = buffer.read_pod<float32>();
    }
    SpringStrength = buffer.read_pod<float32>();
    CompressionDamper = buffer.read_pod<float32>();
    RelaxationDamper = buffer.read_pod<float32>();
    DamperVelocityCap = buffer.read_pod<float32>();
    AntiRollBarStiffness = buffer.read_pod<float32>();
    MaxForce = buffer.read_pod<float32>();
    LatFrictionCounterTorque = buffer.read_pod<float32>();
    LongFrictionCounterTorque = buffer.read_pod<float32>();
    DamperAppliedToLoad = buffer.read_pod<uint8>();
    buffer.skip(3);
    CamberAngle = buffer.read_pod<float32>();
    TrackWidth = buffer.read_pod<float32>();
    XFz = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        XdF0[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        XsM[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        XFM[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        XsG[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        XFG[i] = buffer.read_pod<float32>();
    }
    YFz = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        YdF0[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        YsM[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        YFM[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        YsG[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        YFG[i] = buffer.read_pod<float32>();
    }
    CamberStiffness = buffer.read_pod<float32>();
    Steered = buffer.read_pod<uint8>();
    Driven = buffer.read_pod<uint8>();
    buffer.skip(2);
    Inertia = buffer.read_pod<float32>();
    MaxBrakeTorque = buffer.read_pod<float32>();
    MaxHandbrakeTorque = buffer.read_pod<float32>();
}

