void ADFTypes::Attribute::read(IO::File& buffer) {
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        AttributeName = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        TextRefName = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    AttributeId = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        UpgradeScript = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    MainOwner = buffer.read_pod<uint32>();
    buffer.skip(4);
    PartLevels.read(buffer);
}

void ADFTypes::Attribute::print(std::ostream &out) const {
    out << "AttributeName: " << AttributeName << "\n";
    out << "TextRefName: " << TextRefName << "\n";
    out << "AttributeId: " << AttributeId << "\n";
    out << "UpgradeScript: " << UpgradeScript << "\n";
    out << "MainOwner: " << MainOwner << "\n";
    out << "PartLevels: \n";
    PartLevels.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::Attribute::to_json() const {
    nlohmann::json _res;
    _res["AttributeName"] = AttributeName;
    _res["TextRefName"] = TextRefName;
    _res["AttributeId"] = AttributeId;
    _res["UpgradeScript"] = UpgradeScript;
    _res["MainOwner"] = MainOwner;
    _res["PartLevels"] = PartLevels.to_json();
    return _res;
}

